def transpose(text):
    """Transpose ``text``: rows become columns and columns become rows.

    Rows of the input keep their characters in their original columns, so
    shorter rows are implicitly padded on the right with spaces.  Trailing
    spaces produced by that padding are stripped from each output row, which
    keeps the leading spaces that belong to real input characters.
    """
    if not text:
        return ""

    lines = text.splitlines()
    width = max(len(line) for line in lines)

    rows = []
    for column in range(width):
        rows.append(
            "".join(
                line[column] if column < len(line) else " "
                for line in lines
            ).rstrip(" ")
        )

    # Columns that only ever held padding carry no input characters.
    while rows and not rows[-1]:
        rows.pop()

    return "\n".join(rows)
